_DPAD_ARCS: tuple[tuple[str, float, float], ...] = (
    ("Up", -135.0, -45.0),
    ("Right", -45.0, 45.0),
    ("Down", 45.0, 135.0),
    ("Left", 135.0, 225.0),
)

_TOKEN = re.compile(
    r"[MmLlHhVvCcSsQqTtAaZz]|[-+]?(?:\d+\.\d+|\d+|\.\d+)(?:[eE][-+]\d+)?"
)


def _n(value: float) -> str:
    rounded = round(float(value), 1)
    if abs(rounded - round(rounded)) < 1e-9:
        return str(int(round(rounded)))
    return f"{rounded:.1f}"


def _pt(cx: float, cy: float, radius: float, deg: float) -> str:
    angle = math.radians(deg)
    return f"{_n(cx + radius * math.cos(angle))},{_n(cy + radius * math.sin(angle))}"


def _wedge(cx: float, cy: float, outer: float, inner: float, start: float, end: float) -> str:
    return (
        f"M{_pt(cx, cy, outer, start)} A{_n(outer)},{_n(outer)} 0 0 1 {_pt(cx, cy, outer, end)} "
        f"L{_pt(cx, cy, inner, end)} A{_n(inner)},{_n(inner)} 0 0 0 {_pt(cx, cy, inner, start)} Z"
    )


def _circle(cx: float, cy: float, radius: float) -> str:
    return (
        f"M{_n(cx - radius)},{_n(cy)} A{_n(radius)},{_n(radius)} 0 1 0 {_n(cx + radius)},{_n(cy)} "
        f"A{_n(radius)},{_n(radius)} 0 1 0 {_n(cx - radius)},{_n(cy)} Z"
    )


def _commands(d: str):
    tokens = _TOKEN.findall(d)
    i = 0
    while i < len(tokens):
        cmd = tokens[i]
        i += 1
        if cmd in "Zz":
            yield cmd, ()
            continue
        if cmd in "MmLl":
            pair = (float(tokens[i]), float(tokens[i + 1]))
            i += 2
            yield cmd, pair
            continue
        if cmd in "Aa":
            args = tuple(float(tok) for tok in tokens[i : i + 7])
            i += 7
            yield cmd, args
            continue
        raise ValueError(f"unsupported path command {cmd!r}")


def _path_points(d: str) -> list[tuple[float, float]]:
    points: list[tuple[float, float]] = []
    for cmd, args in _commands(d):
        if cmd in "MmLl":
            points.append(args)
        elif cmd in "Aa":
            points.append((args[5], args[6]))
    return points


def _translate_path(d: str, ox: float, oy: float) -> str:
    parts: list[str] = []
    for cmd, args in _commands(d):
        if cmd in "Zz":
            parts.append("Z")
            continue
        if cmd in "MmLl":
            x, y = args
            parts.append(f"{cmd}{_n(x - ox)},{_n(y - oy)}")
            continue
        rx, ry, rot, large, sweep, x, y = args
        parts.append(
            f"{cmd}{_n(rx)},{_n(ry)} {_n(rot)} {_n(large)} {_n(sweep)} {_n(x - ox)},{_n(y - oy)}"
        )
    return " ".join(parts)


def _source_entries() -> tuple[tuple[str, str, str], ...]:
    entries: list[tuple[str, str, str]] = []
    for name, d in _SOURCE_PATHS[:8]:
        entries.append((name, "path", d))
    for name, start, end in _DPAD_ARCS:
        entries.append((name, "wedge", _wedge(_DPAD_CX, _DPAD_CY, _PAD, _OK_R, start, end)))
    entries.append(("OK", "ok", _circle(_DPAD_CX, _DPAD_CY, _OK_R)))
    for name, d in _SOURCE_PATHS[8:]:
        entries.append((name, "path", d))
    return tuple(entries)


def _crop_origin_and_size() -> tuple[int, int, int, int]:
    xs: list[float] = []
    ys: list[float] = []
    for _name, _kind, d in _source_entries():
        for x, y in _path_points(d):
            xs.append(round(float(x), 1))
            ys.append(round(float(y), 1))
    min_x = math.floor(min(xs)) - HK_TIGHT_PAD
    min_y = math.floor(min(ys)) - HK_TIGHT_PAD
    max_x = math.ceil(max(xs)) + HK_TIGHT_PAD
    max_y = math.ceil(max(ys)) + HK_TIGHT_PAD
    return min_x, min_y, max_x - min_x, max_y - min_y


CROP_X, CROP_Y, CROP_W, CROP_H = _crop_origin_and_size()
CROP_ORIGIN = (CROP_X, CROP_Y)
DESIGN_SIZE = (CROP_W, CROP_H)


def _wedge_box(start: float, end: float, cx: float, cy: float) -> tuple[float, float, float, float]:
    mid = math.radians((start + end) / 2)
    radius = (_PAD + _OK_R) / 2
    x = cx + radius * math.cos(mid)
    y = cy + radius * math.sin(mid)
    return (x - 26, y - 14, 52, 28)


def _aabb(d: str) -> tuple[float, float, float, float]:
    pts = [(round(float(x), 1), round(float(y), 1)) for x, y in _path_points(d)]
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)
    return (min_x, min_y, max_x - min_x, max_y - min_y)


@dataclass(frozen=True)
class Rect:
    slot: int
    x: int
    y: int
    w: int
    h: int


@dataclass(frozen=True)
class Shape:
    slot: int
    d: str
    label_box: tuple[float, float, float, float] | None


def _shapes() -> tuple[Shape, ...]:
    cx = _DPAD_CX - CROP_X
    cy = _DPAD_CY - CROP_Y
    arcs = {name: (start, end) for name, start, end in _DPAD_ARCS}
    out: list[Shape] = []
    for name, kind, d in _source_entries():
        translated = _translate_path(d, CROP_X, CROP_Y)
        if kind == "wedge":
            start, end = arcs[name]
            box: tuple[float, float, float, float] | None = _wedge_box(start, end, cx, cy)
        elif kind == "ok":
            box = (cx - _OK_R, cy - _OK_R, _OK_R * 2, _OK_R * 2)
        else:
            box = _aabb(translated)
            x, y, w, h = box
            half = w / 2
            if name in ("Plus", "Minus"):
                box = (x, y, half, h)
            elif name in ("Vol +", "Vol -"):
                box = (x + half, y, half, h)
        out.append(Shape(slot=_SLOTS[name], d=translated, label_box=box))
    return tuple(out)


RECTS: tuple[Rect, ...] = ()
SHAPES: tuple[Shape, ...] = _shapes()
